async function initChatWatch(){
  if(chatWatchPromise||onlineCh)return chatWatchPromise||Promise.resolve(true);
  chatWatchPromise=(async()=>{
    const lib=await loadSupabase();
    if(onlineCh)return true;
    chatWatchClient=lib.createClient(SUPABASE_URL,SUPABASE_KEY,{auth:{persistSession:false,autoRefreshToken:false,detectSessionInUrl:false},realtime:{params:{eventsPerSecond:6}}});
    chatWatchCh=chatWatchClient.channel(ONLINE_CHANNEL,{config:{broadcast:{self:false}}});
    chatWatchCh.on('broadcast',{event:'chat'},({payload})=>onGlobalChat(payload));
    chatWatchCh.subscribe();
    return true;
  })().catch(e=>{console.warn('[PokéSenda PvP Chat Watch]',e);chatWatchPromise=null;return false;});
  return chatWatchPromise;
}
