function renderOnline(){const host=$('pkPvpOnlineList');if(!host)return;if(!onlinePlayers.length){host.innerHTML='<div class="pk-pvp-empty">No hay otros entrenadores conectados ahora.</div>';return;}host.innerHTML=onlinePlayers.map(p=>{const tv=trainerVisual(p.trainerId,'front'),team=Array.isArray(p.teamPreview)?p.teamPreview:[];return `<div class="pk-pvp-player"><img src="${esc(tv.src||'')}" alt=""><div><b>${esc(p.name||'Entrenador')}</b><small>${esc(regionLabel(p.region))} · ${Number(p.teamCount||0)}/6 en Formación</small><div class="pk-pvp-team-preview">${team.slice(0,6).map(x=>`<img src="${staticSprite(x.dex,!!x.shiny,false)}" title="${esc(x.name)} Nv.${Number(x.level||1)}">`).join('')}</div></div><button class="mini-btn" data-pvp-challenge="${esc(p.id)}">⚔ Desafiar</button></div>`;}).join('');host.querySelectorAll('[data-pvp-challenge]').forEach(b=>b.onclick=()=>challengePlayer(b.dataset.pvpChallenge));}

