function setResultRankStatus(text,tone=''){const el=$('pkPvpResultRankStatus');if(!el)return;el.textContent=text;el.dataset.tone=tone;}
async function submitClassifiedResult(payload,retry=false){
  const matchId=String(payload?.matchId||'');if(!matchId)return;
  const prev=pvpResultSubmitState.get(matchId);if(prev==='done'||(prev==='pending'&&!retry))return;
  pvpResultSubmitState.set(matchId,'pending');
  try{
    const players=Array.isArray(payload?.players)?payload.players:[];
    if(players.length<2)throw new Error('Faltan los dos entrenadores del duelo.');
    const acc=await ensurePvpProfile();
    if(!acc.slotId||!acc.secret||!acc.publicId)throw new Error('Tu Perfil Online no está vinculado al Cloud Save.');
    const a=players[0],b=players[1],aPublic=String(a?.publicId||''),bPublic=String(b?.publicId||'');
    if(!aPublic||!bPublic||aPublic===bPublic)throw new Error('Faltan las identidades públicas de los dos entrenadores.');
    if(String(acc.publicId)!==aPublic&&String(acc.publicId)!==bPublic)throw new Error('Tu Perfil Online no coincide con este duelo.');
    const winnerClientId=String(payload.winnerId||'draw'),draw=winnerClientId==='draw';
    let winnerPublicId=null;
    if(!draw){const w=players.find(x=>String(x?.id||'')===winnerClientId);winnerPublicId=String(w?.publicId||'');if(!winnerPublicId)throw new Error('No se pudo identificar al ganador.');}
    const out=await pvpRpc('pokesenda_pvp_record_match_v2',{
      p_slot_id:acc.slotId,
      p_secret:acc.secret,
      p_match_id:matchId,
      p_player_a:aPublic,
      p_player_b:bPublic,
      p_winner_public_id:draw?null:winnerPublicId,
      p_is_draw:draw,
      p_reason:String(payload.reason||'ko')||'ko',
      p_elapsed_seconds:Math.round(Number(payload.elapsed||0))
    });
    const row=Array.isArray(out)?out[0]:out;
    if(!row?.counted)throw new Error('Supabase no confirmó el registro del duelo.');
    setResultRankStatus('🏆 Resultado registrado en la Clasificación 1v1.','ok');
    pvpResultSubmitState.set(matchId,'done');
    if(!$('pkPvpRankingOverlay')?.classList.contains('hidden'))loadRanking(true);
  }catch(e){
    console.warn('[PokéSenda PvP Ranking]',e);
    setResultRankStatus('⚠️ No se pudo registrar este duelo en la clasificación.');
    pvpResultSubmitState.delete(matchId);
    if(!retry)setTimeout(()=>submitClassifiedResult(payload,true),1800);
  }
}

