async function joinRoom(code,role='guest'){await initOnline();if(!sb)return;code=String(code||'').toUpperCase().replace(/[^A-Z0-9]/g,'').slice(0,8);if(code.length<4){setStatus('Escribe un código de sala válido.','bad');return;}await leaveRoom(false);roomCode=code;roomRole=role;roomJoinedAt=now();roomReady=false;roomTeam=null;roomTeams=new Map();roomStarted=false;roomStartPending=false;roomCh=sb.channel(ROOM_PREFIX+code,{config:{presence:{key:clientId},broadcast:{self:false}}});roomCh.on('presence',{event:'sync'},syncRoom).on('broadcast',{event:'team'},({payload})=>{if(payload?.playerId&&Array.isArray(payload.team))roomTeams.set(String(payload.playerId),payload.team);maybeStartRoom();}).on('broadcast',{event:'start'},({payload})=>onRoomStart(payload)).on('broadcast',{event:'battle_state'},({payload})=>onBattleState(payload)).on('broadcast',{event:'battle_fx'},({payload})=>playBattleFx(payload)).on('broadcast',{event:'potion_open'},({payload})=>onPotionOpen(payload)).on('broadcast',{event:'potion_close'},({payload})=>onPotionClose(payload)).on('broadcast',{event:'potion_use'},({payload})=>onPotionUse(payload)).on('broadcast',{event:'speed_vote'},({payload})=>onSpeedVote(payload)).on('broadcast',{event:'forfeit'},({payload})=>onForfeit(payload)).on('broadcast',{event:'result'},({payload})=>onBattleResult(payload)).on('broadcast',{event:'leave'},({payload})=>{if(payload?.playerId!==clientId){roomReady=false;renderRoomPlayers();}}).subscribe(async status=>{if(status==='SUBSCRIBED'){await trackRoom();setStatus(`Sala ${code} conectada`,'online');renderLobby();setTimeout(syncRoom,80);}else if(status==='CHANNEL_ERROR'||status==='TIMED_OUT'){setStatus('No se pudo abrir la sala.','bad');}});renderLobby();}
async function trackRoom(){if(!roomCh)return;const id=currentIdentity(currentRegion);try{await roomCh.track({...id,role:roomRole,joinedAt:roomJoinedAt,ready:roomReady});}catch(_){}}
function syncRoom(){if(!roomCh)return;roomPlayers=flattenPresence(roomCh.presenceState()).sort((a,b)=>Number(a.joinedAt||0)-Number(b.joinedAt||0));if(roomPlayers.length>2&&!roomPlayers.slice(0,2).some(x=>String(x.id)===clientId)){setStatus('La sala ya está llena.','bad');leaveRoom(false);return;}renderRoomPlayers();maybeStartRoom();}
function renderRoomPlayers(){const host=$('pkPvpRoomPlayers');if(!host)return;if(!roomPlayers.length){host.innerHTML='<div class="pk-pvp-empty">Esperando presencia de la sala…</div>';return;}host.innerHTML=roomPlayers.slice(0,2).map(p=>{const me=String(p.id)===clientId,tv=trainerVisual(p.trainerId,'front'),team=Array.isArray(p.teamPreview)?p.teamPreview:[];return `<div class="pk-pvp-player ${me?'me':''} ${p.ready?'ready':''}"><img src="${esc(tv.src||'')}" alt=""><div><b>${esc(p.name||'Entrenador')}${me?' · Tú':''}</b><small>${esc(regionLabel(p.region))} · ${Number(p.teamCount||0)}/6 · ${p.ready?'LISTO':'Preparando'}</small><div class="pk-pvp-team-preview">${team.slice(0,6).map(x=>`<img src="${staticSprite(x.dex,!!x.shiny,false)}" title="${esc(x.name)} Nv.${Number(x.level||1)}">`).join('')}</div></div><span>${p.ready?'✅':'⏳'}</span></div>`;}).join('');}
async function toggleReady(){if(!roomCh||roomStarted||roomStartPending)return;const busy=regionBusy(currentRegion);if(busy?.run||busy?.gym){setStatus('Detén la Expedición o Gimnasio antes de marcar LISTO.','bad');return;}const t=buildTeamSnapshot('global');if(t.length!==6){setStatus(`Necesitas exactamente 6 Pokémon en la Formación Global. Tienes ${t.length}/6.`,'bad');return;}roomReady=!roomReady;roomTeam=roomReady?t:null;if(roomReady){roomTeams.set(clientId,t);try{await roomCh.send({type:'broadcast',event:'team',payload:{playerId:clientId,team:t}});}catch(_){}}else roomTeams.delete(clientId);await trackRoom();renderLobby();setTimeout(maybeStartRoom,90);}
function hostId(){const h=roomPlayers.filter(x=>x.role==='host').sort((a,b)=>Number(a.joinedAt||0)-Number(b.joinedAt||0))[0];return String(h?.id||roomPlayers[0]?.id||'');}
async function maybeStartRoom(){
  if(!roomCh||roomStarted||roomStartPending||roomPlayers.length!==2)return;
  const players=roomPlayers.slice(0,2);
  if(!players[0]?.ready||!players[1]?.ready)return;
  const idA=String(players[0].id||''),idB=String(players[1].id||'');
  const teamA=idA===clientId?roomTeam:roomTeams.get(idA),teamB=idB===clientId?roomTeam:roomTeams.get(idB);
  if(!teamA||!teamB){
    if(roomReady&&roomTeam){try{await roomCh.send({type:'broadcast',event:'team',payload:{playerId:clientId,team:roomTeam}});}catch(_){}}
    return;
  }
  if(hostId()!==clientId)return;
  roomStartPending=true;
  try{
    const payload={
      matchId:'m_'+randId(),hostId:clientId,roomCode,
      players:players.map(x=>({id:String(x.id),publicId:String(x.publicId||''),name:String(x.name||'Entrenador'),trainerId:String(x.trainerId||'red'),region:String(x.region||'kanto')})),
      teamA:clone(teamA),teamB:clone(teamB),startedAt:now()
    };
    await roomCh.send({type:'broadcast',event:'start',payload});
    onRoomStart(payload);
  }catch(e){
    console.warn('[PokéSenda PvP Start]',e);
    roomStarted=false;
    setStatus('No se pudo iniciar el duelo. Vuelve a pulsar LISTO.','bad');
  }finally{roomStartPending=false;}
}
