async function leaveRoom(show=true){stopEngine();if(roomCh){try{await roomCh.send({type:'broadcast',event:'leave',payload:{playerId:clientId}})}catch(_){ }try{await sb?.removeChannel(roomCh)}catch(_){ }}roomCh=null;roomCode='';roomRole='';roomReady=false;roomTeam=null;roomTeams=new Map();roomPlayers=[];roomStarted=false;roomStartPending=false;battleView=null;if(show)renderLobby();}

function onRoomStart(payload){
  if(!payload?.matchId||!roomCh||roomStarted)return;
  const players=Array.isArray(payload.players)?payload.players:[];
  const me=players.find(x=>String(x.id)===clientId),other=players.find(x=>String(x.id)!==clientId);
  if(!me||!other||!Array.isArray(payload.teamA)||!Array.isArray(payload.teamB)||payload.teamA.length!==6||payload.teamB.length!==6){
    setStatus('La sala no recibió correctamente los dos equipos. Quita LISTO y vuelve a intentarlo.','bad');
    return;
  }
  applyPvpTheme(currentRegion);roomStarted=true;roomStartPending=false;pvpBattleTab='log';pvpPotionOpen=false;pvpPotionPending=false;pvpClearSpeedVoteIntent();$('pkPvpPotionOverlay')?.classList.add('hidden');pvpSetBattleTab('log');const fb=$('pkPvpForfeit');if(fb){fb.disabled=false;fb.textContent='Rendirse';}closeLobby();$('pkPvpResultOverlay')?.classList.add('hidden');$('pkPvpBattleOverlay')?.classList.remove('hidden');$('pkPvpBattleTitle').textContent=`${me.name||'Tú'} vs ${other.name||'Rival'}`;$('pkPvpLeftLabel').textContent=me.name||'Tu equipo';$('pkPvpRightLabel').textContent=other.name||'Equipo rival';renderTrainers(me,other);
  if(String(payload.hostId)===clientId){startHostEngine(payload,payload.teamA,payload.teamB);}else{battleView={matchId:payload.matchId,players,elapsed:0,a:[],b:[],aSlots:[],bSlots:[],logs:[],potionUses:Object.fromEntries(players.map(p=>[String(p.id),0])),pauseOwners:{},paused:false,speed:1,speedVotes:{'1':{},'3':{},'5':{}}};$('pkPvpConn').textContent='● conectado al anfitrión';$('pkPvpConn').classList.add('live');}
}
