function commonType(side){const x=active(side);if(x.length!==3)return null;let c=[...(x[0].e.types||[])];for(const a of x.slice(1))c=c.filter(t=>a.e.types.includes(t));return c[0]||null;}
function effective(e,slot){let atk=e.atk,spAtk=e.spAtk,def=e.def,spDef=e.spDef,cd=e.cd,reduction=e.reduction||0,crit=e.crit||0,support=1;const p={...POS[slot]},m=e.mods||{};if(e.status?.type==='burn')atk*=.75;if(slot===0){p.def+=.01*Number(m.guardRank||0);p.reduction+=.0015*Number(m.guardRank||0);}if(slot===1){p.offense+=.01*Number(m.assaultRank||0);p.crit+=.0015*Number(m.assaultRank||0);}if(slot===2){p.speed+=.01*Number(m.supportRank||0);p.support+=.015*Number(m.supportRank||0)+Number(m.supportSkill||0);}if(p.def){def*=p.def;spDef*=p.def;}if(p.reduction)reduction+=p.reduction;if(p.offense){atk*=p.offense;spAtk*=p.offense;}if(p.crit)crit+=p.crit;if(p.speed)cd/=p.speed;if(p.support)support*=p.support;if(commonType(e.side)){atk*=1.05;spAtk*=1.05;support*=1.05;}if(e.powerTime>0){atk*=1+e.powerBuff;spAtk*=1+e.powerBuff;}if(e.guardTime>0)reduction+=e.guard;if(e.hasteTime>0)cd/=1+e.haste;return {atk,spAtk,def,spDef,cd:Math.max(.18,cd),reduction:Math.min(.65,reduction),crit:Math.min(.9,crit),support};}
