function majorStatus(m){if(m?.statusType)return {type:m.statusType,chance:probabilityValue(m.statusChance,1)};const n=m?.name||'';if(n==='Llamarada')return{type:'burn',chance:.30};if(['Ascua','Lanzallamas','Colmillo Ígneo'].includes(n))return{type:'burn',chance:.10};if(['Impactrueno','Rayo'].includes(n))return{type:'paralysis',chance:.10};if(['Chispa','Descarga','Trueno','Golpe Cuerpo','Lengüetazo'].includes(n))return{type:'paralysis',chance:.30};if(['Aguijón Venenoso','Picotazo Veneno','Bomba Lodo'].includes(n))return{type:'poison',chance:.30};if(['Veneno Cruzado','Ácido'].includes(n))return{type:'poison',chance:.10};if(['Rayo Hielo','Ventisca'].includes(n))return{type:'freeze',chance:.10};if(n==='Hidropulso')return{type:'confusion',chance:.20};if(['Confusión','Psicorrayo'].includes(n))return{type:'confusion',chance:.10};return null;}
function supportStatus(m,rank){if(m?.statusType)return{type:m.statusType,chance:Math.min(1,probabilityValue(m.statusChance,1))};const n=m?.name||'',bonus=.004*(Math.max(1,rank||1)-1);if(['Onda Trueno','Polvo Paralizador'].includes(n))return{type:'paralysis',chance:Math.min(.99,.90+bonus)};if(['Hipnosis','Canto'].includes(n))return{type:'sleep',chance:Math.min(.99,.75+bonus)};if(n==='Espora')return{type:'sleep',chance:Math.min(.99,.95+bonus)};if(n==='Supersónico')return{type:'confusion',chance:Math.min(.99,.85+bonus)};if(n==='Tóxico')return{type:'poison',chance:Math.min(.99,.80+bonus)};return null;}
function applyStatus(e,type,chance=1){if(!e?.alive||Math.random()>=chance)return false;if(type==='confusion'){if(e.confusionTurns>0)return false;e.confusionTurns=2+Math.floor(Math.random()*4);return true;}const types=Array.isArray(e.types)?e.types:[];if((type==='burn'&&types.includes('fire'))||(type==='poison'&&(types.includes('poison')||types.includes('steel')))||(type==='paralysis'&&types.includes('electric'))||(type==='freeze'&&types.includes('ice')))return false;if(e.status)return false;e.status={type,turns:type==='sleep'?2+Math.floor(Math.random()*3):0};e.statusTick=3;return true;}
