function onBattleState(payload){if(!payload?.matchId||engine)return;battleView=payload;pvpPotionPending=false;pvpReconcileSpeedVoteIntent(payload);renderRemoteState(payload);if(pvpPotionOpen)renderPvpPotion();$('pkPvpConn').classList.add('live');}
function onBattleResult(payload){if(!payload?.matchId)return;if(engine&&String(engine.meta.matchId)!==String(payload.matchId))return;showResult(payload);}
