function onSpeedVote(payload){if(!validBattlePayload(payload))return;pvpApplySpeedVote(payload.playerId,payload.speed,payload.vote!==false);}
async function pvpSendSpeedVoteRequest(payload){if(!roomCh)return false;try{await roomCh.send({type:'broadcast',event:'speed_vote',payload});return true;}catch(_){return false;}}
