function onPotionClose(payload){if(!validBattlePayload(payload))return;pvpSetPauseOwner(payload.playerId,false);}
function pvpSideForPlayer(playerId){if(!engine)return null;return String(engine.meta.players?.[0]?.id||'')===String(playerId)?'a':String(engine.meta.players?.[1]?.id||'')===String(playerId)?'b':null;}
function pvpApplyPotion(playerId,itemId,targetIndex){if(!engine||engine.finished)return false;playerId=String(playerId||'');itemId=String(itemId||'');const side=pvpSideForPlayer(playerId),it=PVP_MEDICINES[itemId];if(!side||!it)return false;engine.potionUses=engine.potionUses||{};const used=Math.max(0,Number(engine.potionUses[playerId]||0));if(used>=POTION_LIMIT)return false;const team=teamOf(side),idx=Number(targetIndex),e=team[idx];if(!e?.alive)return false;let worked=false,detail='';if(it.healPct&&e.hp<e.maxHp){const actual=heal(e,e,e.maxHp*it.healPct);if(actual>0){worked=true;detail=`+${Math.ceil(actual)} PS`;const slot=slotsOf(side).findIndex(x=>x===idx);if(slot>=0)emitBattleFx({kind:'heal',fromSide:side,fromSlot:slot,toSide:side,toSlot:slot,type:'normal',amount:actual});}}else if(it.curesStatus&&(e.status?.type||e.confusionTurns>0)){e.status=null;e.statusTick=3;e.confusionTurns=0;worked=true;detail='estado curado';const slot=slotsOf(side).findIndex(x=>x===idx);if(slot>=0)emitBattleFx({kind:'status',fromSide:side,fromSlot:slot,toSide:side,toSlot:slot,type:'normal',text:'CURADO'});}if(!worked)return false;engine.potionUses[playerId]=Math.min(POTION_LIMIT,used+1);logBattle(`🧪 ${pvpPlayerName(playerId)} · Botiquín ${engine.potionUses[playerId]}/${POTION_LIMIT}: ${it.name} en ${e.name} · ${detail}.`);renderEngineForLocal();broadcastState(true);return true;}
function onPotionUse(payload){if(!validBattlePayload(payload))return;pvpApplyPotion(payload.playerId,payload.itemId,payload.targetIndex);}
async function pvpOpenPotion(){const s=engine?publicState():battleView;if(!s?.matchId||s.finished)return;const used=Math.max(0,Number(s.potionUses?.[clientId]||0));if(used>=POTION_LIMIT){const el=$('pkPvpConn');if(el)el.textContent='🧪 Botiquín agotado · 3/3';return;}pvpPotionOpen=true;pvpPotionPending=false;$('pkPvpPotionOverlay')?.classList.remove('hidden');renderPvpPotion();const payload={playerId:clientId,matchId:String(s.matchId)};if(engine)pvpSetPauseOwner(clientId,true);else try{await roomCh?.send({type:'broadcast',event:'potion_open',payload});}catch(_){}}
async function pvpClosePotion(){if(!pvpPotionOpen){$('pkPvpPotionOverlay')?.classList.add('hidden');return;}const s=engine?publicState():battleView;pvpPotionOpen=false;pvpPotionPending=false;$('pkPvpPotionOverlay')?.classList.add('hidden');if(!s?.matchId)return;const payload={playerId:clientId,matchId:String(s.matchId)};if(engine)pvpSetPauseOwner(clientId,false);else try{await roomCh?.send({type:'broadcast',event:'potion_close',payload});}catch(_){}}
async function pvpUsePotion(itemId,targetIndex){const s=engine?publicState():battleView;if(!s?.matchId||pvpPotionPending)return;const used=Math.max(0,Number(s.potionUses?.[clientId]||0));if(used>=POTION_LIMIT)return;const payload={playerId:clientId,matchId:String(s.matchId),itemId:String(itemId),targetIndex:Number(targetIndex)};if(engine){pvpApplyPotion(clientId,payload.itemId,payload.targetIndex);renderPvpPotion();}else{pvpPotionPending=true;renderPvpPotion();try{await roomCh?.send({type:'broadcast',event:'potion_use',payload});}catch(_){pvpPotionPending=false;renderPvpPotion();}}}
function renderPvpPotion(){const box=$('pkPvpPotionOverlay');if(!box||box.classList.contains('hidden'))return;const s=engine?publicState():battleView;if(!s?.players?.length)return;const o=orientState(s),used=Math.max(0,Number(s.potionUses?.[clientId]||0)),exhausted=used>=POTION_LIMIT;if(!PVP_MEDICINES[pvpPotionSelected])pvpPotionSelected='potion';$('pkPvpPotionUses').textContent=`${used}/${POTION_LIMIT} usos`;$('pkPvpPotionItems').innerHTML=Object.entries(PVP_MEDICINES).map(([id,it])=>`<button class="gym-potion-item pk-pvp-potion-item-virtual ${id===pvpPotionSelected?'selected':''}" data-pvp-potion="${id}" ${exhausted||pvpPotionPending?'disabled':''}><span class="gym-potion-icon">${it.icon}</span><b>${it.name}</b><small>${it.desc}</small><em>VIRTUAL</em></button>`).join('');$('pkPvpPotionItems').querySelectorAll('[data-pvp-potion]').forEach(b=>b.onclick=()=>{pvpPotionSelected=b.dataset.pvpPotion;renderPvpPotion();});const it=PVP_MEDICINES[pvpPotionSelected];$('pkPvpPotionTargets').innerHTML=(o.me||[]).map((e,i)=>{const pct=Math.max(0,Math.min(100,e.hp/Math.max(1,e.maxHp)*100)),needsHeal=!!it.healPct&&e.hp<e.maxHp,needsStatus=!!it.curesStatus&&!!(e.status?.type||Number(e.confusionTurns||0)>0),usable=!exhausted&&!pvpPotionPending&&e.alive&&(needsHeal||needsStatus);return `<button class="gym-potion-target ${e.alive?'':'ko'}" data-pvp-potion-target="${i}" ${usable?'':'disabled'}><img src="${staticSprite(e.dex,!!e.shiny,false)}"><span><b>${esc(e.name)}</b><small>Nv.${e.level} · ${Math.ceil(e.hp)}/${Math.ceil(e.maxHp)} PS</small><i><u style="width:${pct}%"></u></i></span></button>`;}).join('');$('pkPvpPotionTargets').querySelectorAll('[data-pvp-potion-target]').forEach(b=>b.onclick=()=>pvpUsePotion(pvpPotionSelected,Number(b.dataset.pvpPotionTarget)));$('pkPvpPotionWait').textContent=pvpPotionPending?'⏳ Esperando confirmación del anfitrión…':exhausted?'Botiquín agotado · utilizaste tus 3 oportunidades.':'La pelea seguirá pausada hasta que todos los entrenadores cierren su Botiquín.';}
function onForfeit(payload){if(!payload?.playerId)return;const matchId=String(payload.matchId||battleView?.matchId||engine?.meta?.matchId||'');if(engine&&matchId&&String(engine.meta.matchId)!==matchId)return;if(engine){const loser=String(payload.playerId),loserSide=String(engine.meta.players?.[0]?.id||'')===loser?'a':'b',name=engine.meta.players?.find(x=>String(x.id)===loser)?.name||'El rival';logBattle(`🏳️ ${name} se rinde.`);finishEngine(otherSide(loserSide));return;}if(String(payload.playerId)!==clientId){const name=(battleView?.players||roomPlayers).find(x=>String(x.id)===String(payload.playerId))?.name||'El rival';const el=$('pkPvpConn');if(el)el.textContent=`🏳️ ${name} se rindió · esperando resultado`;}}
async function forfeitBattle(){if(!roomCh)return;const confirmFn=window.PokeSendaGameConfirm||window.gameConfirm;let ok=true;if(typeof confirmFn==='function')ok=await confirmFn({title:'Rendirse del Duelo',message:'El duelo terminará inmediatamente y tu rival ganará. No perderás objetos, PS reales ni progreso.',confirmText:'Rendirse',cancelText:'Seguir luchando',tone:'danger',symbol:'🏳️'});else ok=confirm('¿Rendirse del Duelo Online?');if(!ok)return;const matchId=String(engine?.meta?.matchId||battleView?.matchId||'');const btn=$('pkPvpForfeit');if(btn){btn.disabled=true;btn.textContent='🏳️ Rindiéndote…';}if(engine){const meSide=String(engine.meta.players?.[0]?.id)===clientId?'a':'b';logBattle('🏳️ Te has rendido.');try{await roomCh.send({type:'broadcast',event:'forfeit',payload:{playerId:clientId,matchId}});}catch(_){}finishEngine(otherSide(meSide));return;}try{await roomCh.send({type:'broadcast',event:'forfeit',payload:{playerId:clientId,matchId}});const other=(battleView?.players||roomPlayers).find(x=>String(x.id)!==clientId),payload={matchId:matchId||'m_'+randId(),winnerId:String(other?.id||'draw'),players:(battleView?.players||roomPlayers).map(x=>({id:x.id,publicId:x.publicId||'',name:x.name,trainerId:x.trainerId,region:x.region})),teamA:battleView?.a||[],teamB:battleView?.b||[],elapsed:Number(battleView?.elapsed||0),reason:'forfeit'};setTimeout(()=>{if(!$('pkPvpBattleOverlay')?.classList.contains('hidden'))showResult(payload);},1800);}catch(_){if(btn){btn.disabled=false;btn.textContent='Rendirse';}}}


function statusHtml(e){const out=[];if(e.status?.type&&STATUS_META[e.status.type])out.push(STATUS_META[e.status.type].join(''));if(e.confusionTurns>0)out.push('💫CONF');return out.join(' ');}
function monHtml(e,side,slot,index){const pct=Math.max(0,Math.min(100,e.hp/e.maxHp*100)),back=side==='player',src=sprite(e.dex,e.shiny,back),fallback=staticSprite(e.dex,e.shiny,back),primary=TYPE_COLORS[e.types?.[0]]||'#607fb2',types=(e.types||[]).map(t=>`<span class="gym-type-chip" style="--type:${TYPE_COLORS[t]||'#777'}">${esc(t)}</span>`).join(''),item=e.item?.name?`${e.item.icon||'🎒'} ${esc(e.item.name)}`:'';return `<div class="gym-mon ${side} ${e.alive?'':'ko'}" data-side="${side}" data-slot="${slot}" style="--gym-size:138px;--gym-type:${primary}"><div class="gym-mon-hud"><div class="gym-role-mini role-${slot}">${POS[slot]?.name||'Puesto'}</div><div class="gym-mon-name">${esc(e.name)}</div><div class="gym-mon-sub"><span>Nv.${e.level}</span><span class="gym-hptext">${Math.max(0,Math.ceil(e.hp))}/${e.maxHp}</span></div><div class="gym-hpbar"><div class="gym-hpfill ${pct<=20?'low':pct<=50?'mid':''}" style="width:${pct}%"></div></div><div class="gym-status-mini">${esc(statusHtml(e))}</div><div class="gym-held-mini">${item}</div><div class="gym-type-row">${types}</div></div><img class="gym-mon-sprite" src="${src}" data-fallback="${fallback}" onerror="if(this.src!==this.dataset.fallback)this.src=this.dataset.fallback" alt="${esc(e.name)}"></div>`;}
function reserveHtml(arr,slots){const set=new Set(slots.filter(x=>x!=null));return arr.map((e,i)=>{const pct=Math.max(0,Math.min(100,e.hp/e.maxHp*100));return `<div class="gym-reserve-mon ${set.has(i)?'active':''} ${e.alive?'':'ko'}"><img src="${staticSprite(e.dex,e.shiny,false)}"><small>${esc(e.name)}</small><small>${e.alive?`Nv.${e.level}`:'KO'}</small><div class="gym-reserve-hp"><i style="width:${pct}%"></i></div></div>`;}).join('');}
function formatTime(v){v=Math.max(0,Math.floor(Number(v)||0));return `${String(Math.floor(v/60)).padStart(2,'0')}:${String(v%60).padStart(2,'0')}`;}
function orientState(s){const p0=String(s.players?.[0]?.id||'')===clientId;return p0?{me:s.a,them:s.b,mySlots:s.aSlots,theirSlots:s.bSlots}:{me:s.b,them:s.a,mySlots:s.bSlots,theirSlots:s.aSlots};}
function pvpSetBattleTab(tab='log'){pvpBattleTab=tab==='damage'?'damage':'log';const dmg=pvpBattleTab==='damage';$('pkPvpLogTab')?.classList.toggle('active',!dmg);$('pkPvpDamageTab')?.classList.toggle('active',dmg);$('pkPvpBattleLog')?.classList.toggle('hidden',dmg);$('pkPvpBattleDamage')?.classList.toggle('hidden',!dmg);const s=engine?publicState():battleView;if(dmg&&s)renderPvpDamage(s);}
function pvpStatTeamHtml(arr,title){const total=(k)=>arr.reduce((n,e)=>n+Number(e?.stats?.[k]||0),0),dmg=total('damage'),taken=total('taken'),healv=total('healing');return `<div class="pk-pvp-stat-team"><div class="pk-pvp-stat-head"><b>${esc(title)}</b><span>Daño ${Math.round(dmg).toLocaleString('es-CL')}</span><span>Recib. ${Math.round(taken).toLocaleString('es-CL')}</span><span>Cura ${Math.round(healv).toLocaleString('es-CL')}</span></div>${arr.map(e=>{const st=e.stats||{};return `<div class="pk-pvp-stat-row ${e.alive?'':'ko'}"><div class="pk-pvp-stat-mon"><img src="${staticSprite(e.dex,!!e.shiny,false)}"><span><b>${esc(e.name)}</b><small>Nv.${e.level}${e.alive?'':' · KO'}</small></span></div><div class="pk-pvp-stat-num"><b>${Math.round(st.damage||0).toLocaleString('es-CL')}</b><small>daño</small></div><div class="pk-pvp-stat-num"><b>${Math.round(st.taken||0).toLocaleString('es-CL')}</b><small>recibido</small></div><div class="pk-pvp-stat-num"><b>${Math.round(st.healing||0).toLocaleString('es-CL')}</b><small>cura</small></div></div>`;}).join('')}</div>`;}
function renderPvpDamage(s){const box=$('pkPvpBattleDamage');if(!box||!s)return;const o=orientState(s),me=(s.players||[]).find(x=>String(x.id)===clientId),other=(s.players||[]).find(x=>String(x.id)!==clientId);box.innerHTML=pvpStatTeamHtml(o.me||[],me?.name||'TU EQUIPO')+pvpStatTeamHtml(o.them||[],other?.name||'RIVAL');}
function renderPvpControlState(s){if(!s)return;const used=Math.max(0,Number(s.potionUses?.[clientId]||0)),btn=$('pkPvpPotionBtn');if(btn){btn.textContent=`🧪 Botiquín ${used}/${POTION_LIMIT}`;btn.disabled=!!s.finished||used>=POTION_LIMIT;}const currentSpeed=Number(s.speed||1),votes=pvpVotesForDisplay(s);document.querySelectorAll('#pkPvpSpeedVotes [data-pvp-speed]').forEach(b=>{const target=Number(b.dataset.pvpSpeed||1),count=Object.keys(votes?.[String(target)]||{}).length,mine=!!votes?.[String(target)]?.[clientId],current=target===currentSpeed;b.classList.toggle('current',current);b.classList.toggle('voted',!current&&mine);b.disabled=!!s.finished||!!s.paused||current;b.setAttribute('aria-pressed',mine?'true':'false');b.textContent=current?`×${target} ACTUAL`:`×${target} · ${count}/2`;});const owners=Object.keys(s.pauseOwners||{}).filter(id=>s.pauseOwners?.[id]);const note=$('pkPvpPauseNote'),conn=$('pkPvpConn');if(owners.length){const names=owners.map(id=>(s.players||[]).find(p=>String(p.id)===String(id))?.name||'Entrenador');if(note)note.textContent='⏸ Botiquín';if(conn){conn.textContent=`⏸ pausa · ${names.join(' + ')}`;conn.classList.add('live');}}else{if(note)note.textContent=`⚡ ×${currentSpeed}`;if(conn){conn.textContent=engine?'● anfitrión · sincronizando':'● conectado · anfitrión sincronizando';conn.classList.add('live');}}}
function renderState(s){if(!s)return;const o=orientState(s),myAct=o.mySlots.map((idx,slot)=>idx==null?null:{e:o.me[idx],slot,index:idx}).filter(x=>x?.e?.alive),opAct=o.theirSlots.map((idx,slot)=>idx==null?null:{e:o.them[idx],slot,index:idx}).filter(x=>x?.e?.alive);$('pkPvpPlayerSide').innerHTML=myAct.map(x=>monHtml(x.e,'player',x.slot,x.index)).join('');$('pkPvpEnemySide').innerHTML=opAct.map(x=>monHtml(x.e,'enemy',x.slot,x.index)).join('');$('pkPvpPlayerReserve').innerHTML=reserveHtml(o.me,o.mySlots);$('pkPvpEnemyReserve').innerHTML=reserveHtml(o.them,o.theirSlots);$('pkPvpTimer').textContent=`${formatTime(s.elapsed)} / 03:00`;$('pkPvpScore').textContent=`${o.me.filter(x=>x.alive).length} vs ${o.them.filter(x=>x.alive).length}`;$('pkPvpBattleLog').innerHTML=(s.logs||[]).map(x=>`<div class="gym-log-line">${esc(x)}</div>`).join('');renderPvpControlState(s);if(pvpBattleTab==='damage')renderPvpDamage(s);if(pvpPotionOpen)renderPvpPotion();}
function renderEngineForLocal(){if(engine)renderState(publicState());}
function renderRemoteState(s){battleView=s;renderState(s);}
function showResult(payload){if(engine&&String(engine.meta?.matchId||'')===String(payload?.matchId||'')){if(engineTimer){clearInterval(engineTimer);engineTimer=null;}engine.finished=true;}pvpPotionOpen=false;pvpPotionPending=false;$('pkPvpPotionOverlay')?.classList.add('hidden');const fb=$('pkPvpForfeit');if(fb){fb.disabled=false;fb.textContent='Rendirse';}$('pkPvpBattleOverlay')?.classList.add('hidden');$('pkPvpResultOverlay')?.classList.remove('hidden');const win=String(payload.winnerId||'draw'),meWin=win===clientId,draw=win==='draw',winner=payload.players?.find(x=>String(x.id)===win);$('pkPvpResultIcon').textContent=draw?'🤝':meWin?'🏆':'⚔️';$('pkPvpResultTitle').textContent=draw?'¡Empate!':meWin?'¡Victoria en Duelo Online!':`${winner?.name||'Tu rival'} gana el duelo`;$('pkPvpResultText').innerHTML=`Duración: <b>${formatTime(payload.elapsed||0)}</b>${payload.reason==='time'?'<br>⏱️ Tiempo agotado: se desempató por Pokémon vivos y luego PS totales restantes.':''}<br>El resultado competitivo se guarda aparte: no modifica tu save, PS, objetos ni Pokédolares.`;setResultRankStatus('🏆 Sincronizando resultado clasificatorio…');submitClassifiedResult(payload);const myFirst=String(payload.players?.[0]?.id||'')===clientId,team=myFirst?(payload.teamA||[]):(payload.teamB||[]);$('pkPvpResultTeam').innerHTML=team.slice(0,6).map(x=>`<img src="${staticSprite(x.dex,!!x.shiny,false)}" title="${esc(x.name||'Pokémon')}">`).join('');}
function closeResult(){$('pkPvpResultOverlay')?.classList.add('hidden');}

