  const duel=e.target.closest?.('.pk-pvp-btn');
  if(duel){e.preventDefault();e.stopPropagation();openLobby(activeRegionFrom(duel));return;}
  if(e.target.closest?.('[data-region],#regionSelectOverlay,#pkRegionRuntimeRoot'))setTimeout(installButtons,180);
